#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/mise/tasks/upgrade-power.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Apply the pmset/nvram power profile (prompts for sudo)"
# MISE hide=true
# MISE dir="~"
# MISE tools={uv="latest", python="3.14"}

# Everything `defaults`-based lives in [bootstrap.macos.defaults]
# (conf.d/macos-defaults.toml); mise bootstrap has no pmset/nvram support, so
# this task carries those. macOS updates reset these settings, so `updateall`
# re-applies them weekly.

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402

# Settings when running strictly on Battery Power (-b)
# Conserves power with tight 5-minute timeouts, lowered screen brightness, and Low Power Mode
BATTERY = [
  ("displaysleep", "5"),
  ("disksleep", "5"),
  ("sleep", "5"),
  ("womp", "0"),
  ("powernap", "0"),
  ("lessbright", "1"),
  ("halfdim", "0"),
  ("lowpowermode", "1"),
]

# Settings when connected to a Power Adapter (-c)
# Expands timeouts to 30 minutes, keeps performance uncapped, and enables background processing
CHARGER = [
  ("displaysleep", "30"),
  ("disksleep", "30"),
  ("sleep", "30"),
  ("womp", "1"),
  ("powernap", "1"),
  ("lessbright", "0"),
  ("halfdim", "0"),
  ("lowpowermode", "0"),
]

# Hardware Policy Settings across ALL Power States (-a)
# Eliminates phantom wakes, handles custom deep-standby triggers, and disables TTY idle blockers
ALL = [
  ("proximitywake", "0"),
  ("autorestart", "1"),
  ("lidwake", "1"),
  ("acwake", "1"),
  ("ttyskeepawake", "0"),
  ("standby", "1"),
  ("standbydelayhigh", "3600"),
  ("standbydelaylow", "300"),
  ("tcpkeepalive", "1"),
]


def run(*cmd):
  """Run the command. When it fails, stop the task with its code."""
  rc = subprocess.run(cmd, check=False).returncode
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def main():
  helpers.print_header("Baking custom Hardware Power Management profiles...")

  for flag, settings in (("-b", BATTERY), ("-c", CHARGER), ("-a", ALL)):
    for key, value in settings:
      run("sudo", "pmset", flag, key, value)

  # Apply hardware-level AutoBoot configuration via NVRAM logic
  helpers.print_subheader("Setting firmware AutoBoot arguments...")
  run("sudo", "nvram", "AutoBoot=%01")

  helpers.print_success("Power profiles calibrated and locked in successfully!")


if __name__ == "__main__":
  main()
